import{_ as t,o,c as a,a2 as r}from"./chunks/framework.yZB1U4Nl.js";const p=JSON.parse('{"title":"Interface: HostContext","description":"","frontmatter":{"editLink":false},"headers":[],"relativePath":"api/host/interfaces/HostContext.md","filePath":"api/host/interfaces/HostContext.md"}'),s={name:"api/host/interfaces/HostContext.md"};function n(c,e,l,d,i,h){return o(),a("div",null,[...e[0]||(e[0]=[r('<p><a href="./../../packages">@oona/vlo</a> / <a href="./../">host</a> / HostContext</p><h1 id="interface-hostcontext" tabindex="-1">Interface: HostContext <a class="header-anchor" href="#interface-hostcontext" aria-label="Permalink to &quot;Interface: HostContext&quot;">​</a></h1><p>Defined in: <a href="https://github.com/oonalab/vlo/blob/a81c115e42e129b4efe8fd86066744a4f8bc3670/sdk/ts/sdk/src/host/context.ts#L96" target="_blank" rel="noreferrer">sdk/ts/sdk/src/host/context.ts:96</a></p><p>The shared state every host function takes as its first argument. Built by <code>createHost</code>.</p><h2 id="properties" tabindex="-1">Properties <a class="header-anchor" href="#properties" aria-label="Permalink to &quot;Properties&quot;">​</a></h2><h3 id="activities" tabindex="-1">activities <a class="header-anchor" href="#activities" aria-label="Permalink to &quot;activities&quot;">​</a></h3><blockquote><p><strong>activities</strong>: <code>Map</code>&lt;<code>string</code>, <a href="./ActivityRegistration"><code>ActivityRegistration</code></a>&gt;</p></blockquote><p>Defined in: <a href="https://github.com/oonalab/vlo/blob/a81c115e42e129b4efe8fd86066744a4f8bc3670/sdk/ts/sdk/src/host/context.ts#L110" target="_blank" rel="noreferrer">sdk/ts/sdk/src/host/context.ts:110</a></p><p>Registered activities by name.</p><hr><h3 id="auth" tabindex="-1">auth <a class="header-anchor" href="#auth" aria-label="Permalink to &quot;auth&quot;">​</a></h3><blockquote><p><strong>auth</strong>: <a href="./AuthConfig"><code>AuthConfig</code></a></p></blockquote><p>Defined in: <a href="https://github.com/oonalab/vlo/blob/a81c115e42e129b4efe8fd86066744a4f8bc3670/sdk/ts/sdk/src/host/context.ts#L118" target="_blank" rel="noreferrer">sdk/ts/sdk/src/host/context.ts:118</a></p><p>Credentials this host checks and sends.</p><hr><h3 id="basepath" tabindex="-1">basePath? <a class="header-anchor" href="#basepath" aria-label="Permalink to &quot;basePath?&quot;">​</a></h3><blockquote><p><code>optional</code> <strong>basePath?</strong>: <code>string</code></p></blockquote><p>Defined in: <a href="https://github.com/oonalab/vlo/blob/a81c115e42e129b4efe8fd86066744a4f8bc3670/sdk/ts/sdk/src/host/context.ts#L127" target="_blank" rel="noreferrer">sdk/ts/sdk/src/host/context.ts:127</a></p><p>Path prefix this host is mounted under, normalised to <code>/api/vlo</code>. The router strips it before matching and every URL built from <code>publicUrl</code> carries it.</p><hr><h3 id="blob" tabindex="-1">blob <a class="header-anchor" href="#blob" aria-label="Permalink to &quot;blob&quot;">​</a></h3><blockquote><p><strong>blob</strong>: <a href="./BlobStore"><code>BlobStore</code></a></p></blockquote><p>Defined in: <a href="https://github.com/oonalab/vlo/blob/a81c115e42e129b4efe8fd86066744a4f8bc3670/sdk/ts/sdk/src/host/context.ts#L100" target="_blank" rel="noreferrer">sdk/ts/sdk/src/host/context.ts:100</a></p><p>Where payloads over the inline limit are offloaded.</p><hr><h3 id="drain" tabindex="-1">drain? <a class="header-anchor" href="#drain" aria-label="Permalink to &quot;drain?&quot;">​</a></h3><blockquote><p><code>optional</code> <strong>drain?</strong>: (<code>options?</code>) =&gt; <code>Promise</code>&lt;<a href="./DrainResult"><code>DrainResult</code></a>&gt;</p></blockquote><p>Defined in: <a href="https://github.com/oonalab/vlo/blob/a81c115e42e129b4efe8fd86066744a4f8bc3670/sdk/ts/sdk/src/host/context.ts#L140" target="_blank" rel="noreferrer">sdk/ts/sdk/src/host/context.ts:140</a></p><p>Ticks until idle. Present only when this process holds the <code>orchestrator</code> role.</p><h4 id="parameters" tabindex="-1">Parameters <a class="header-anchor" href="#parameters" aria-label="Permalink to &quot;Parameters&quot;">​</a></h4><h5 id="options" tabindex="-1">options? <a class="header-anchor" href="#options" aria-label="Permalink to &quot;options?&quot;">​</a></h5><p><a href="./DrainOptions"><code>DrainOptions</code></a></p><h4 id="returns" tabindex="-1">Returns <a class="header-anchor" href="#returns" aria-label="Permalink to &quot;Returns&quot;">​</a></h4><p><code>Promise</code>&lt;<a href="./DrainResult"><code>DrainResult</code></a>&gt;</p><hr><h3 id="events" tabindex="-1">events <a class="header-anchor" href="#events" aria-label="Permalink to &quot;events&quot;">​</a></h3><blockquote><p><strong>events</strong>: <code>EventEmitter</code></p></blockquote><p>Defined in: <a href="https://github.com/oonalab/vlo/blob/a81c115e42e129b4efe8fd86066744a4f8bc3670/sdk/ts/sdk/src/host/context.ts#L134" target="_blank" rel="noreferrer">sdk/ts/sdk/src/host/context.ts:134</a></p><p>In-memory side channel. <code>emit</code> carries <code>cmd.emit</code> payloads, <code>warning</code> carries the dispatcher&#39;s, and <code>task_scheduled</code> wakes a long-poll the moment a task is written.</p><hr><h3 id="inprocess" tabindex="-1">inProcess <a class="header-anchor" href="#inprocess" aria-label="Permalink to &quot;inProcess&quot;">​</a></h3><blockquote><p><strong>inProcess</strong>: <a href="./../classes/InProcessTracker"><code>InProcessTracker</code></a></p></blockquote><p>Defined in: <a href="https://github.com/oonalab/vlo/blob/a81c115e42e129b4efe8fd86066744a4f8bc3670/sdk/ts/sdk/src/host/context.ts#L142" target="_blank" rel="noreferrer">sdk/ts/sdk/src/host/context.ts:142</a></p><p>In-process handlers still owing a result; <code>drain</code> waits on it between passes.</p><hr><h3 id="journal" tabindex="-1">journal <a class="header-anchor" href="#journal" aria-label="Permalink to &quot;journal&quot;">​</a></h3><blockquote><p><strong>journal</strong>: <a href="./Journal"><code>Journal</code></a></p></blockquote><p>Defined in: <a href="https://github.com/oonalab/vlo/blob/a81c115e42e129b4efe8fd86066744a4f8bc3670/sdk/ts/sdk/src/host/context.ts#L98" target="_blank" rel="noreferrer">sdk/ts/sdk/src/host/context.ts:98</a></p><p>Durable state and task queue.</p><hr><h3 id="kernel" tabindex="-1">kernel <a class="header-anchor" href="#kernel" aria-label="Permalink to &quot;kernel&quot;">​</a></h3><blockquote><p><strong>kernel</strong>: <a href="./Kernel"><code>Kernel</code></a></p></blockquote><p>Defined in: <a href="https://github.com/oonalab/vlo/blob/a81c115e42e129b4efe8fd86066744a4f8bc3670/sdk/ts/sdk/src/host/context.ts#L102" target="_blank" rel="noreferrer">sdk/ts/sdk/src/host/context.ts:102</a></p><p>The wasm kernel. A proxy that throws until <code>start()</code> has loaded it.</p><hr><h3 id="kick" tabindex="-1">kick <a class="header-anchor" href="#kick" aria-label="Permalink to &quot;kick&quot;">​</a></h3><blockquote><p><strong>kick</strong>: () =&gt; <code>void</code></p></blockquote><p>Defined in: <a href="https://github.com/oonalab/vlo/blob/a81c115e42e129b4efe8fd86066744a4f8bc3670/sdk/ts/sdk/src/host/context.ts#L136" target="_blank" rel="noreferrer">sdk/ts/sdk/src/host/context.ts:136</a></p><p>Set when this process holds the <code>orchestrator</code> role.</p><h4 id="returns-1" tabindex="-1">Returns <a class="header-anchor" href="#returns-1" aria-label="Permalink to &quot;Returns&quot;">​</a></h4><p><code>void</code></p><hr><h3 id="namespace" tabindex="-1">namespace <a class="header-anchor" href="#namespace" aria-label="Permalink to &quot;namespace&quot;">​</a></h3><blockquote><p><strong>namespace</strong>: <code>string</code></p></blockquote><p>Defined in: <a href="https://github.com/oonalab/vlo/blob/a81c115e42e129b4efe8fd86066744a4f8bc3670/sdk/ts/sdk/src/host/context.ts#L106" target="_blank" rel="noreferrer">sdk/ts/sdk/src/host/context.ts:106</a></p><p>Namespace new runs are created in.</p><hr><h3 id="now" tabindex="-1">now <a class="header-anchor" href="#now" aria-label="Permalink to &quot;now&quot;">​</a></h3><blockquote><p><strong>now</strong>: () =&gt; <code>number</code></p></blockquote><p>Defined in: <a href="https://github.com/oonalab/vlo/blob/a81c115e42e129b4efe8fd86066744a4f8bc3670/sdk/ts/sdk/src/host/context.ts#L104" target="_blank" rel="noreferrer">sdk/ts/sdk/src/host/context.ts:104</a></p><p>Clock for journaled timestamps, epoch milliseconds.</p><h4 id="returns-2" tabindex="-1">Returns <a class="header-anchor" href="#returns-2" aria-label="Permalink to &quot;Returns&quot;">​</a></h4><p><code>number</code></p><hr><h3 id="publicurl" tabindex="-1">publicUrl? <a class="header-anchor" href="#publicurl" aria-label="Permalink to &quot;publicUrl?&quot;">​</a></h3><blockquote><p><code>optional</code> <strong>publicUrl?</strong>: <code>string</code></p></blockquote><p>Defined in: <a href="https://github.com/oonalab/vlo/blob/a81c115e42e129b4efe8fd86066744a4f8bc3670/sdk/ts/sdk/src/host/context.ts#L122" target="_blank" rel="noreferrer">sdk/ts/sdk/src/host/context.ts:122</a></p><p>Base URL other processes can reach this host on; fills <code>complete_url</code> on a push.</p><hr><h3 id="queues" tabindex="-1">queues <a class="header-anchor" href="#queues" aria-label="Permalink to &quot;queues&quot;">​</a></h3><blockquote><p><strong>queues</strong>: <code>Record</code>&lt;<code>string</code>, <a href="./QueueConfig"><code>QueueConfig</code></a>&gt;</p></blockquote><p>Defined in: <a href="https://github.com/oonalab/vlo/blob/a81c115e42e129b4efe8fd86066744a4f8bc3670/sdk/ts/sdk/src/host/context.ts#L116" target="_blank" rel="noreferrer">sdk/ts/sdk/src/host/context.ts:116</a></p><p>Per-queue delivery configuration.</p><hr><h3 id="roles" tabindex="-1">roles <a class="header-anchor" href="#roles" aria-label="Permalink to &quot;roles&quot;">​</a></h3><blockquote><p><strong>roles</strong>: <code>ReadonlySet</code>&lt;<a href="./../type-aliases/Role"><code>Role</code></a>&gt;</p></blockquote><p>Defined in: <a href="https://github.com/oonalab/vlo/blob/a81c115e42e129b4efe8fd86066744a4f8bc3670/sdk/ts/sdk/src/host/context.ts#L120" target="_blank" rel="noreferrer">sdk/ts/sdk/src/host/context.ts:120</a></p><p>Roles this process holds.</p><hr><h3 id="signals" tabindex="-1">signals <a class="header-anchor" href="#signals" aria-label="Permalink to &quot;signals&quot;">​</a></h3><blockquote><p><strong>signals</strong>: <code>Map</code>&lt;<code>string</code>, <a href="./SignalRegistration"><code>SignalRegistration</code></a>&gt;</p></blockquote><p>Defined in: <a href="https://github.com/oonalab/vlo/blob/a81c115e42e129b4efe8fd86066744a4f8bc3670/sdk/ts/sdk/src/host/context.ts#L112" target="_blank" rel="noreferrer">sdk/ts/sdk/src/host/context.ts:112</a></p><p>Registered signals by name.</p><hr><h3 id="streampollms" tabindex="-1">streamPollMs <a class="header-anchor" href="#streampollms" aria-label="Permalink to &quot;streamPollMs&quot;">​</a></h3><blockquote><p><strong>streamPollMs</strong>: <code>number</code></p></blockquote><p>Defined in: <a href="https://github.com/oonalab/vlo/blob/a81c115e42e129b4efe8fd86066744a4f8bc3670/sdk/ts/sdk/src/host/context.ts#L129" target="_blank" rel="noreferrer">sdk/ts/sdk/src/host/context.ts:129</a></p><p>How often an open SSE stream looks for new journal events.</p><hr><h3 id="tick" tabindex="-1">tick? <a class="header-anchor" href="#tick" aria-label="Permalink to &quot;tick?&quot;">​</a></h3><blockquote><p><code>optional</code> <strong>tick?</strong>: () =&gt; <code>Promise</code>&lt;<a href="./TickCounts"><code>TickCounts</code></a>&gt;</p></blockquote><p>Defined in: <a href="https://github.com/oonalab/vlo/blob/a81c115e42e129b4efe8fd86066744a4f8bc3670/sdk/ts/sdk/src/host/context.ts#L138" target="_blank" rel="noreferrer">sdk/ts/sdk/src/host/context.ts:138</a></p><p>One dispatcher pass. Present only when this process holds the <code>orchestrator</code> role.</p><h4 id="returns-3" tabindex="-1">Returns <a class="header-anchor" href="#returns-3" aria-label="Permalink to &quot;Returns&quot;">​</a></h4><p><code>Promise</code>&lt;<a href="./TickCounts"><code>TickCounts</code></a>&gt;</p><hr><h3 id="workers" tabindex="-1">workers <a class="header-anchor" href="#workers" aria-label="Permalink to &quot;workers&quot;">​</a></h3><blockquote><p><strong>workers</strong>: <a href="./../../index/interfaces/Worker"><code>Worker</code></a>[]</p></blockquote><p>Defined in: <a href="https://github.com/oonalab/vlo/blob/a81c115e42e129b4efe8fd86066744a4f8bc3670/sdk/ts/sdk/src/host/context.ts#L114" target="_blank" rel="noreferrer">sdk/ts/sdk/src/host/context.ts:114</a></p><p>Workers this process runs in-process, by the queues they serve.</p><hr><h3 id="workflows" tabindex="-1">workflows <a class="header-anchor" href="#workflows" aria-label="Permalink to &quot;workflows&quot;">​</a></h3><blockquote><p><strong>workflows</strong>: <code>Map</code>&lt;<code>string</code>, <a href="./../../index/interfaces/Workflow"><code>Workflow</code></a>&lt;<code>unknown</code>, <code>unknown</code>&gt;&gt;</p></blockquote><p>Defined in: <a href="https://github.com/oonalab/vlo/blob/a81c115e42e129b4efe8fd86066744a4f8bc3670/sdk/ts/sdk/src/host/context.ts#L108" target="_blank" rel="noreferrer">sdk/ts/sdk/src/host/context.ts:108</a></p><p>Registered workflows by name.</p>',115)])])}const k=t(s,[["render",n]]);export{p as __pageData,k as default};
